#import "TFAIProtocol.h"
#import <Security/Security.h>
static NSString *const TFConnectionsKey=@"TFAI.Connections.v1";
static NSString *const TFDefaultKey=@"TFAI.DefaultConnection.v1";
static NSString *const TFOverridesKey=@"TFAI.ProjectConnections.v1";
static NSMutableDictionary *KeyQuery(NSString *identifier){return [@{(__bridge id)kSecClass:(__bridge id)kSecClassGenericPassword,(__bridge id)kSecAttrService:@"com.xuegao.tweakforge.ai.connection.v1",(__bridge id)kSecAttrAccount:identifier} mutableCopy];}
@implementation TFAIConnections
+ (NSArray<NSDictionary *> *)all{@synchronized(self){NSArray *a=[NSUserDefaults.standardUserDefaults arrayForKey:TFConnectionsKey];return [a isKindOfClass:NSArray.class]?a:@[];}}
+ (NSString *)secret:(NSString *)identifier{if(!identifier.length)return @"";NSMutableDictionary *query=KeyQuery(identifier);query[(__bridge id)kSecReturnData]=@YES;query[(__bridge id)kSecMatchLimit]=(__bridge id)kSecMatchLimitOne;CFTypeRef result=NULL;OSStatus s=SecItemCopyMatching((__bridge CFDictionaryRef)query,&result);if(s!=errSecSuccess)return @"";NSData *data=CFBridgingRelease(result);return [[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding]?:@"";}
+ (BOOL)save:(NSDictionary *)input secret:(NSString *)secret error:(NSError **)error{@synchronized(self){
 NSString *identifier=[input[@"id"] isKindOfClass:NSString.class]?input[@"id"]:@"";if(!identifier.length||identifier.length>128){if(error)*error=TFAIError(10,@"连接 ID 无效，请重新创建连接");return NO;}
 NSMutableDictionary *c=[NSMutableDictionary new];for(NSString *key in @[@"id",@"name",@"protocol",@"baseURL",@"model"]){id v=input[key];if(v&&![v isKindOfClass:NSString.class]){if(error)*error=TFAIError(11,@"连接设置包含非文本字段");return NO;}c[key]=v?:@"";}
 if(![c[@"protocol"] length])c[@"protocol"]=@"chat";c[@"allowLANHTTP"]=@([input[@"allowLANHTTP"] boolValue]);c[@"toolsEnabled"]=@(!input[@"toolsEnabled"]||[input[@"toolsEnabled"] boolValue]);if(!TFAIEndpoint(c,NO,error))return NO;
 if(![c[@"name"] length])c[@"name"]=[NSURL URLWithString:c[@"baseURL"]].host?:@"模型连接";
 NSMutableArray *models=[NSMutableArray new];for(id value in ([input[@"models"] isKindOfClass:NSArray.class]?input[@"models"]:@[]))if([value isKindOfClass:NSString.class]&&[value length]&&[value length]<256&&![models containsObject:value]&&models.count<10000)[models addObject:value];c[@"models"]=models;if([input[@"modelDiscovery"] isKindOfClass:NSString.class])c[@"modelDiscovery"]=[input[@"modelDiscovery"] substringToIndex:MIN(2000,[input[@"modelDiscovery"] length])];
 // Keep only bounded, declarative overrides; never persist arbitrary request JSON.
 if([input[@"thinkingOverrides"] isKindOfClass:NSDictionary.class]){NSMutableDictionary *map=[NSMutableDictionary new];for(id key in input[@"thinkingOverrides"]){if(map.count>=200)break;if(![key isKindOfClass:NSString.class]||[key length]>4096)continue;id raw=input[@"thinkingOverrides"][key];if(![raw isKindOfClass:NSDictionary.class]||![@[@"reasoning_effort",@"thinking",@"enable_thinking",@"disabled"] containsObject:raw[@"wire"]])continue;NSMutableArray *levels=[NSMutableArray new];for(id level in ([raw[@"levels"] isKindOfClass:NSArray.class]?raw[@"levels"]:@[]))if([@[@"minimal",@"low",@"medium",@"high",@"xhigh",@"ultra",@"max",@"enabled"] containsObject:level]&&![levels containsObject:level])[levels addObject:level];map[key]=@{@"wire":raw[@"wire"],@"levels":levels};}c[@"thinkingOverrides"]=map;}
 BOOL sameModel=YES;for(NSDictionary *old in [self all])if([old[@"id"] isEqual:identifier]&&(![old[@"model"] isEqual:c[@"model"]]||![old[@"baseURL"] isEqual:c[@"baseURL"]]||![old[@"protocol"] isEqual:c[@"protocol"]]))sameModel=NO;
 if(sameModel&&[input[@"capabilities"] isKindOfClass:NSDictionary.class]){NSMutableDictionary *caps=[NSMutableDictionary new];for(NSString *k in @[@"text",@"stream",@"image",@"tools"]){id v=input[@"capabilities"][k];if([@[@"supported",@"unsupported",@"unknown"] containsObject:v])caps[k]=v;}c[@"capabilities"]=caps;}
 if(sameModel&&secret==nil&&[input[@"testResults"] isKindOfClass:NSDictionary.class]){NSMutableDictionary *results=[NSMutableDictionary new];for(NSString *key in @[@"text",@"stream",@"image",@"tools"]){id r=input[@"testResults"][key];if(![r isKindOfClass:NSDictionary.class]||![@[@"pass",@"fail",@"unknown"] containsObject:r[@"state"]])continue;NSString *detail=[r[@"detail"] isKindOfClass:NSString.class]?r[@"detail"]:@"";results[key]=@{@"state":r[@"state"],@"detail":[detail substringToIndex:MIN(detail.length,1200)],@"diagnostics":TFAISanitizeProbeDiagnostics(r[@"diagnostics"], [self secret:identifier])};}c[@"testResults"]=results;if([input[@"testedAt"] isKindOfClass:NSNumber.class])c[@"testedAt"]=input[@"testedAt"];}
 if(secret!=nil){[c removeObjectForKey:@"capabilities"];[c removeObjectForKey:@"testResults"];}
 if(secret!=nil&&secret.length==0){OSStatus s=SecItemDelete((__bridge CFDictionaryRef)KeyQuery(identifier));if(s!=errSecSuccess&&s!=errSecItemNotFound){if(error)*error=TFAIError(s,@"钥匙串密钥删除失败；设置未保存");return NO;}}
 if(secret.length){if(secret.length>16384){if(error)*error=TFAIError(12,@"密钥过长");return NO;}NSData *data=[secret dataUsingEncoding:NSUTF8StringEncoding];NSMutableDictionary *query=KeyQuery(identifier);OSStatus s=SecItemUpdate((__bridge CFDictionaryRef)query,(__bridge CFDictionaryRef)@{(__bridge id)kSecValueData:data});if(s==errSecItemNotFound){query[(__bridge id)kSecValueData]=data;query[(__bridge id)kSecAttrAccessible]=(__bridge id)kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly;s=SecItemAdd((__bridge CFDictionaryRef)query,NULL);}if(s!=errSecSuccess){if(error)*error=TFAIError(s,[NSString stringWithFormat:@"钥匙串保存失败（%d）；设置未保存，请检查签名权限",(int)s]);return NO;}}
 NSMutableArray *all=[[self all] mutableCopy];NSUInteger index=[all indexOfObjectPassingTest:^BOOL(NSDictionary *v,NSUInteger i,BOOL *stop){return [v[@"id"] isEqual:identifier];}];if(index==NSNotFound)[all addObject:c];else all[index]=c;[NSUserDefaults.standardUserDefaults setObject:all forKey:TFConnectionsKey];if(![NSUserDefaults.standardUserDefaults stringForKey:TFDefaultKey].length)[NSUserDefaults.standardUserDefaults setObject:identifier forKey:TFDefaultKey];return YES;
}}
+ (void)remove:(NSString *)identifier{@synchronized(self){NSMutableArray *all=[[self all] mutableCopy];NSIndexSet *indices=[all indexesOfObjectsPassingTest:^BOOL(NSDictionary *v,NSUInteger i,BOOL *stop){return [v[@"id"] isEqual:identifier];}];[all removeObjectsAtIndexes:indices];[NSUserDefaults.standardUserDefaults setObject:all forKey:TFConnectionsKey];SecItemDelete((__bridge CFDictionaryRef)KeyQuery(identifier));if([[NSUserDefaults.standardUserDefaults stringForKey:TFDefaultKey] isEqual:identifier])[NSUserDefaults.standardUserDefaults removeObjectForKey:TFDefaultKey];NSMutableDictionary *overrides=[[NSUserDefaults.standardUserDefaults dictionaryForKey:TFOverridesKey] mutableCopy]?:[NSMutableDictionary new];for(NSString *key in overrides.allKeys)if([overrides[key] isEqual:identifier])[overrides removeObjectForKey:key];[NSUserDefaults.standardUserDefaults setObject:overrides forKey:TFOverridesKey];}}
+ (NSDictionary *)effectiveForProject:(NSString *)projectID{@synchronized(self){NSString *override=projectID.length?[NSUserDefaults.standardUserDefaults dictionaryForKey:TFOverridesKey][projectID]:nil;NSString *identifier=override?:[NSUserDefaults.standardUserDefaults stringForKey:TFDefaultKey];for(NSDictionary *c in [self all])if([c[@"id"] isEqual:identifier]){NSMutableDictionary *v=[c mutableCopy];v[@"source"]=override?@"project":@"global";NSError *e=nil;NSURL *url=TFAIEndpoint(c,NO,&e);if(url)v[@"endpoint"]=url.absoluteString;return v;}return nil;}}
+ (void)setConnection:(NSString *)identifier project:(NSString *)projectID{@synchronized(self){BOOL exists=NO;for(NSDictionary *c in [self all])if([c[@"id"] isEqual:identifier])exists=YES;if(identifier.length&&!exists)return;if(projectID.length){NSMutableDictionary *map=[[NSUserDefaults.standardUserDefaults dictionaryForKey:TFOverridesKey] mutableCopy]?:[NSMutableDictionary new];if(identifier.length)map[projectID]=identifier;else[map removeObjectForKey:projectID];[NSUserDefaults.standardUserDefaults setObject:map forKey:TFOverridesKey];}else if(identifier.length)[NSUserDefaults.standardUserDefaults setObject:identifier forKey:TFDefaultKey];else[NSUserDefaults.standardUserDefaults removeObjectForKey:TFDefaultKey];}}
@end
